const HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>TaskForge AI — AI Work Delivered</title><meta name=\"description\" content=\"TaskForge AI delivers fixed-scope digital work.\"><link rel=\"canonical\" href=\"https://taskforge-ai.pages.dev/\"><style>body{font-family:system-ui;margin:0;background:#0b1020;color:#f7f8fc}main{max-width:1000px;margin:auto;padding:64px 22px}.hero{max-width:760px}h1{font-size:clamp(42px,7vw,76px);line-height:.95;margin:0 0 18px}p{color:#b9c0d4;line-height:1.6}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;margin:34px 0}.card,.box{border:1px solid #27304a;border-radius:18px;padding:22px;background:#11182b}.box{max-width:700px}input,textarea,select{width:100%;box-sizing:border-box;margin:7px 0 12px;padding:13px;border-radius:10px;border:1px solid #35405d;background:#0a1020;color:white}button{padding:13px 18px;border:0;border-radius:10px;font-weight:700}.muted{font-size:13px;color:#8992aa}#msg{margin-top:12px;color:#9fe6b8}label{display:block;margin-top:12px}button:disabled{opacity:.6}a{color:#9fe6b8}:focus-visible{outline:3px solid #9fe6b8;outline-offset:3px}</style></head><body><main><section class=\"hero\"><div class=\"muted\">TASKFORGE AI · GLOBAL DIGITAL OPERATIONS</div><h1>AI work.<br>Delivered.</h1><p>Fixed-scope digital work for companies, founders and professionals. Clear intake, verified output, fast delivery.</p></section><section class=\"grid\"><div class=\"card\"><h3>PDF to Excel</h3><p>Convert eligible PDFs into structured spreadsheets with QA.</p></div><div class=\"card\"><h3>Spreadsheet cleanup</h3><p>Clean, normalize and structure spreadsheet data.</p><p><a href=\"/services/crm-csv-cleanup\">CSV &amp; CRM lead cleanup — see sample scope →</a></p><p><a href=\"/services/quick-csv-fix\">Small CSV file? Get a quick scoped quote →</a></p></div><div class=\"card\"><h3>Company list</h3><p>Research and compile company lists with verified results.</p></div><div class=\"card\"><h3>CV writing</h3><p>Create professional CV documents from supplied facts.</p></div></section><section class=\"box\" id=\"b2b\" style=\"margin-bottom:28px\"><p class=\"muted\">NEW: BUSINESS AUTOMATION</p><h2>Remove repetitive work from your operations</h2><p><a href='/services/rfq-catalogue-check'>Distributors: RFQ catalogue-matching and quote precheck →</a></p><p>For service teams, distributors and growing companies: qualify sales leads, organize incoming invoices and purchase orders, or triage support requests. Start with a scoped, measurable pilot and human approval of sensitive decisions.</p><p><a href=\"/automation\" style=\"font-weight:700\">Discuss an AI automation pilot →</a></p><p class=\"muted\">Custom integration is quoted after discovery; no guaranteed savings or automatic deployment are promised.</p></section><section class=\"box\"><h2>Submit your project</h2><p>Choose a service and send your brief. Pricing and delivery time are confirmed after review. No payment is due when you submit.</p><form id=\"order\">\n<label for=\"service\">Service</label><select id=\"service\" name=\"service_slug\" required><option value=\"\">Choose a service</option><option value=\"pdf-to-excel\">PDF to Excel</option><option value=\"spreadsheet-cleanup\">Spreadsheet cleanup</option><option value=\"company-list\">Company list</option><option value=\"cv\">CV writing</option></select>\n<label for=\"name\">Name</label><input id=\"name\" name=\"customer_name\" autocomplete=\"name\" maxlength=\"160\" required>\n<label for=\"email\">Email</label><input id=\"email\" name=\"customer_email\" type=\"email\" autocomplete=\"email\" maxlength=\"254\" required>\n<label for=\"brief\">What do you need delivered?</label><textarea id=\"brief\" name=\"brief\" rows=\"5\" maxlength=\"10000\" required></textarea>\n<label for=\"file\">Supporting file (optional)</label><input id=\"file\" name=\"file\" type=\"file\" accept=\".pdf,.xlsx,.xls,.csv,.docx,.txt,.rtf\" aria-describedby=\"file-help\"><p id=\"file-help\" class=\"muted\">PDF, Excel, CSV, DOCX, TXT or RTF. Maximum 15 MB. Files are stored privately for project review. Upload only files you are authorized to share; do not include passwords or card details.</p>\n<button type=\"submit\">Submit project for review</button><div id=\"msg\" role=\"status\" aria-live=\"polite\"></div></form><p class=\"muted\">Keep your TF reference. Submission does not confirm payment or start delivery.</p></section>\n<section class=\"box\" id=\"account\" style=\"margin-top:28px\"><h2>Your project: status, payment and delivery</h2><p>Sign in with the email used for your project to check its status, review an approved quote or access a checked result. No payment is taken by checking status.</p><form id=\"result-form\"><label for=\"account-email\">Account email</label><input id=\"account-email\" type=\"email\" autocomplete=\"username\" maxlength=\"254\" required><label for=\"account-password\">Password</label><input id=\"account-password\" type=\"password\" autocomplete=\"current-password\" minlength=\"8\" maxlength=\"128\" required><label for=\"order-reference\">Project reference</label><input id=\"order-reference\" placeholder=\"TF-1234ABCD\" pattern=\"TF-[0-9A-Fa-f]{8}\" maxlength=\"11\"><button type=\"submit\">Sign in and get result</button> <button type=\"button\" id=\"create-account\">Create account</button> <button type=\"button\" id=\"pay-order\">Open approved checkout</button> <button type=\"button\" id=\"check-status\">Check project status</button><p id=\"account-msg\" role=\"status\" aria-live=\"polite\"></p><a id=\"result-link\" hidden rel=\"noreferrer\">Download checked CSV</a> <a id=\"payment-link\" hidden rel=\"noreferrer\">Continue to secure Whop checkout</a></form><p class=\"muted\">New account? Create it, confirm your email, then return here. Your password is cleared after each request. Download links expire after one minute.</p></section>\n<script>\nconst form=document.querySelector('#order'),msg=document.querySelector('#msg');\nconst requestedService=new URL(location.href).searchParams.get('service');\nif(['pdf-to-excel','spreadsheet-cleanup','company-list','cv'].includes(requestedService))form.elements.service_slug.value=requestedService;\nform.addEventListener('submit',async event=>{event.preventDefault();const file=form.elements.file.files[0],button=form.querySelector('button');if(file&&file.size>15*1024*1024){msg.textContent='File is too large. Maximum size is 15 MB.';return}button.disabled=true;msg.textContent='Submitting your project…';try{const response=await fetch('/api/order',{method:'POST',body:new FormData(form)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Submission failed.');if(!result.reference)throw new Error('No reference was returned.');msg.textContent='Project received. Your reference is '+result.reference+'. Save this reference. Your project is awaiting scope and price review; no payment has been taken.';form.reset()}catch(error){msg.textContent=error.message+' Your details have been kept. If the connection failed after submission, check with us before sending again.'}finally{button.disabled=false}});\n\nconst resultForm=document.querySelector('#result-form'),accountMsg=document.querySelector('#account-msg'),resultLink=document.querySelector('#result-link');\nconst paymentLink=document.querySelector('#payment-link');\nasync function accountAction(signup,pay=false,statusOnly=false){\n if(!resultForm.reportValidity())return;\n const email=document.querySelector('#account-email').value.trim(),passwordInput=document.querySelector('#account-password'),password=passwordInput.value,reference=document.querySelector('#order-reference').value.trim().toUpperCase();\n if(!signup&&!/^TF-[0-9A-F]{8}$/.test(reference)){accountMsg.textContent='Enter your TF reference from project submission.';return}\n resultLink.hidden=true;resultLink.removeAttribute('href');paymentLink.hidden=true;paymentLink.removeAttribute('href');\n const buttons=[...resultForm.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);accountMsg.textContent=signup?'Creating account…':statusOnly?'Checking your project status…':'Checking your result…';\n try{\n  const response=await fetch(signup?'/api/signup':'/api/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email,password})});\n  const data=await response.json();if(!response.ok)throw new Error(data.error||'Account request failed.');\n  if(signup){accountMsg.textContent='If registration is available for this email, check your inbox to confirm it, then return here to sign in.';return}\n  if(statusOnly){\n   const statusResponse=await fetch('/api/status',{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+data.access_token},body:JSON.stringify({reference})});\n   const project=await statusResponse.json();if(!statusResponse.ok)throw new Error(project.error||'Status unavailable.');\n   const labels={reviewing:'Your brief is awaiting review and pricing. No payment is due.',awaiting_payment:'A quote has been recorded; checkout is available only when payment setup is complete.',paid:'Payment recorded; processing has not finished.',processing:'Your project is being processed.',needs_review:'Your project needs additional quality review.',delivered:'Your checked result is ready. Use Sign in and get result to download.',rejected:'Your project was closed. No download is available.'};\n   accountMsg.textContent='Project '+project.reference+': '+(labels[project.phase]||'Status requires review.')+(Number.isFinite(project.quote_amount_tnd)&&project.quote_amount_tnd>0?' Quote: '+project.quote_amount_tnd+' TND.':'');\n   return;\n  }\n  if(pay){\n   const checkout=await fetch('/api/checkout',{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+data.access_token},body:JSON.stringify({reference})});\n   const result=await checkout.json();if(!checkout.ok)throw new Error(result.error||'Checkout unavailable.');\n   const target=new URL(result.purchase_url);if(target.origin!=='https://whop.com'||target.username||target.password)throw new Error('Checkout unavailable.');\n   paymentLink.href=target.href;paymentLink.hidden=false;accountMsg.textContent='Approved quote: '+result.amount+' '+result.currency+'. Continue to Whop to review and pay. Opening this link does not confirm payment.';return;\n  }\n  const download=await fetch('/api/result',{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+data.access_token},body:JSON.stringify({reference})});\n  const result=await download.json();if(!download.ok)throw new Error(result.error||'Your result is not available yet.');\n  const target=new URL(result.url);if(target.origin!=='https://epkhqmhhzwlbxxypywau.supabase.co'||!target.pathname.startsWith('/storage/v1/object/sign/'))throw new Error('Download unavailable.');\n  resultLink.href=target.href;resultLink.hidden=false;accountMsg.textContent='Your reviewed CSV is ready. Download it within one minute.';\n }catch(error){accountMsg.textContent=error.message}finally{passwordInput.value='';buttons.forEach(b=>b.disabled=false)}\n}\nresultForm.addEventListener('submit',event=>{event.preventDefault();accountAction(false)});\ndocument.querySelector('#create-account').addEventListener('click',()=>accountAction(true));\ndocument.querySelector('#pay-order').addEventListener('click',()=>accountAction(false,true));\ndocument.querySelector('#check-status').addEventListener('click',()=>accountAction(false,false,true));\n\n</script></main></body></html>";

const AUTOMATION_HTML="<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>B2B AI Workflow Automation | TaskForge AI</title>\n<meta name=\"description\" content=\"Scope an AI workflow automation pilot for lead qualification, document intake or support operations. Request a tailored proposal.\">\n<link rel=\"canonical\" href=\"https://taskforge-ai.pages.dev/automation\">\n<style>\nbody{font-family:system-ui;background:#0b1020;color:#f7f8fc;margin:0}main{max-width:1000px;margin:auto;padding:42px 22px}h1{font-size:clamp(36px,6vw,64px);line-height:1.06;margin:0 0 18px}.tag,a{color:#9fe6b8}p{color:#b9c0d4;line-height:1.65}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:14px;margin:24px 0}.card,.box{background:#11182b;border:1px solid #27304a;border-radius:18px;padding:20px}.muted{font-size:13px;color:#9da8c0}label{display:block;margin:15px 0 5px}input,select,textarea{width:100%;box-sizing:border-box;background:#0a1020;color:#fff;border:1px solid #455477;border-radius:10px;padding:12px;font:inherit}button{margin-top:18px;background:#9fe6b8;border:0;border-radius:10px;padding:13px 19px;font-weight:700;cursor:pointer}button:disabled{opacity:.6}.notice{color:#9fe6b8}a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #9fe6b8}\n</style></head><body><main>\n<p class=\"tag\">TASKFORGE AI · B2B WORKFLOW AUTOMATION</p>\n<h1>Automate the repetitive.<br>Keep control of the important.</h1>\n<p>We scope practical automations around your existing tools and business processes. Start with an assessment and a small pilot; confirm integrations, security, measurable outcomes and pricing before implementation.</p>\n<section class=\"box\" aria-label=\"How the pilot works\"><h2>A clear path from problem to pilot</h2><p><strong>1. Describe your workflow:</strong> Share the business process, weekly volume and tools used; no customer records or credentials needed.</p><p><strong>2. Receive a feasibility review:</strong> We identify the safest useful automation, exceptions needing human approval, dependencies and a proposed success measure.</p><p><strong>3. Approve a written pilot scope:</strong> Only after agreeing deliverables, access, pricing and acceptance tests would implementation begin. No automatic charges or guaranteed savings.</p><p class=\"muted\">Try our working browser-only LeadOps CSV demonstration first; its classification is rule-based, not generative AI, and it does not connect to your CRM.</p></section>\n<p><a href=\"#b2b-lead\" style=\"display:inline-block;background:#9fe6b8;color:#071422;font-weight:750;padding:14px 19px;border-radius:9px;text-decoration:none\">Request a free workflow assessment →</a></p>\n<p><a href=\"/automation/demo\">Try a no-signup routing demonstration →</a> (runs locally in your browser with fictional sample requests).</p><p><a href=\"/automation/leadops\" style=\"font-weight:700\">Try LeadOps: import a lead CSV, flag duplicates and export a reviewed queue →</a></p><p><a href=\"/automation/crm-cleanup\" style=\"font-weight:700\">Try our free CRM contact-matching and duplicate-review pilot →</a> — compare two CSV files privately in your browser.</p><p><a href='/services/rfq-catalogue-check' style='font-weight:700'>Distributors: see our RFQ catalogue and quotation precheck offer →</a></p><section class=\"grid\">\n<div class=\"card\"><h2>Lead intake &amp; CRM routing</h2><p>Capture incoming requests, classify them, flag missing details and route qualified leads for follow-up. People approve customer-facing decisions.</p></div>\n<div class=\"card\"><h2>Invoices &amp; order documents</h2><p>Extract structured fields from invoices or purchase orders, identify exceptions, and prepare records for review before ERP/accounting updates.</p></div>\n<div class=\"card\"><h2>Support inbox triage</h2><p>Organize inquiries by intent and urgency, draft suggested responses and route exceptions to your team. No unsupervised promises to customers.</p></div>\n</section>\n<section class=\"box\"><h2>Request an automation assessment</h2>\n<p>Tell us where manual work slows you down. We will review feasibility and propose a pilot scope; this form does not create a paid order.</p>\n<form id=\"b2b-lead\">\n<label for=\"b2b-name\">Your name</label><input id=\"b2b-name\" name=\"name\" maxlength=\"160\" autocomplete=\"name\" required>\n<label for=\"b2b-email\">Work email</label><input id=\"b2b-email\" type=\"email\" name=\"email\" maxlength=\"254\" autocomplete=\"email\" required>\n<label for=\"b2b-company\">Company</label><input id=\"b2b-company\" name=\"company\" maxlength=\"160\" autocomplete=\"organization\" required>\n<label for=\"b2b-workflow\">Primary workflow</label>\n<select id=\"b2b-workflow\" name=\"workflow\" required><option value=\"\">Choose a workflow</option><option value=\"Lead intake and CRM routing\">Lead intake and CRM routing</option><option value=\"Invoice and purchase order intake\">Invoice and purchase order intake</option><option value=\"Support inbox triage\">Support inbox triage</option><option value=\"Other workflow\">Other workflow</option></select>\n<label for=\"b2b-volume\">Approximate items handled each week (optional)</label><input id=\"b2b-volume\" name=\"volume\" maxlength=\"60\" placeholder=\"e.g. 200 emails or 80 invoices\">\n<label for=\"b2b-tools\">Tools currently used (optional)</label><input id=\"b2b-tools\" name=\"tools\" maxlength=\"160\" placeholder=\"e.g. Google Sheets, HubSpot, email\">\n<label for=\"b2b-need\">Where does your team lose time?</label><textarea id=\"b2b-need\" name=\"details\" rows=\"5\" maxlength=\"3000\" minlength=\"15\" required placeholder=\"Describe the current steps, errors and desired result. No private customer data.\"></textarea>\n<label for=\"b2b-budget\">Indicative pilot budget (not a price quote)</label><select id=\"b2b-budget\" name=\"budget\" required><option value=\"\">Select a band</option><option value=\"Exploring budget\">Exploring budget</option><option value=\"Under USD 500\">Under USD 500</option><option value=\"USD 500-2000\">USD 500–2,000</option><option value=\"USD 2000-10000\">USD 2,000–10,000</option><option value=\"USD 10000+\">USD 10,000+</option></select>\n<button type=\"submit\">Request a scoped pilot</button><p id=\"b2b-message\" role=\"status\" aria-live=\"polite\" class=\"notice\"></p>\n</form>\n<p class=\"muted\">Share only work information you are authorized to provide. Do not submit API keys, passwords, financial records or personal customer data. Automations and savings are subject to feasibility and acceptance checks.</p></section>\n<p><a href=\"/\">← Back to TaskForge services</a></p>\n<script>\nconst leadForm=document.querySelector('#b2b-lead');\nconst leadMessage=document.querySelector('#b2b-message');\nleadForm.addEventListener('submit',async event=>{\n event.preventDefault();\n const button=leadForm.querySelector('button[type=\"submit\"]');\n const f=leadForm.elements;\n const need=[f.workflow.value.trim(),f.details.value.trim(),'Weekly volume: '+(f.volume.value.trim()||'not specified'),'Existing tools: '+(f.tools.value.trim()||'not specified')].join('\\n');\n const data={name:f.name.value.trim(),email:f.email.value.trim(),company:f.company.value.trim(),need,budget:f.budget.value};\n button.disabled=true;leadMessage.textContent='Submitting assessment request…';\n try{\n  const response=await fetch('/api/lead',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});\n  const result=await response.json();\n  if(!response.ok||!result.ok)throw new Error(result.error||'We could not save your request.');\n  leadMessage.textContent='Assessment request received. This is not a quote or payment confirmation.';\n  leadForm.reset();\n }catch(error){leadMessage.textContent=error.message+' Keep your details and try again later.'}\n finally{button.disabled=false}\n});\n</script></main></body></html>";

const B2B_DEMO_HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Lead Routing Demonstration | TaskForge AI</title><meta name=\"description\" content=\"Test a rule-based lead and request routing example using fictional messages. No customer data is sent.\"><link rel=\"canonical\" href=\"https://taskforge-ai.pages.dev/automation/demo\"><style>\nbody{font-family:system-ui;background:#0b1020;color:#f7f8fc;margin:0}main{max-width:850px;margin:auto;padding:48px 22px}.muted{color:#a6b0c8}p{line-height:1.6}h1{font-size:clamp(31px,5vw,55px)}.card{background:#11182b;border:1px solid #27304a;border-radius:18px;padding:24px;margin:22px 0}label{display:block;margin:13px 0}textarea,select{box-sizing:border-box;width:100%;padding:12px;border:1px solid #43516c;background:#0a1020;color:white;border-radius:10px;font:inherit}button{cursor:pointer;border:0;border-radius:9px;background:#9fe6b8;padding:12px 19px;font-weight:700;margin:14px 0}a{color:#9fe6b8}a:focus-visible,button:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #9fe6b8}.result{border-top:1px solid #3a465e;padding-top:12px;white-space:pre-wrap}\n</style></head><body><main><p><a href=\"/automation\">← Automation assessment</a></p><h1>See a workflow route itself.</h1><p class=\"muted\">This interactive prototype uses transparent keyword rules and fictional messages. It is not an AI model, a live CRM integration or a verified customer deployment. All processing stays in your browser; no sample text is transmitted.</p>\n<section class=\"card\"><h2>1. Choose a sample inquiry</h2>\n<label for=\"sample\">Fictional scenario</label><select id=\"sample\"><option value=\"lead\">Sales inquiry</option><option value=\"support\">Customer support</option><option value=\"finance\">Purchase order / finance</option><option value=\"ambiguous\">Unclear request</option></select>\n<label for=\"message\">Example incoming message (do not paste confidential customer information)</label><textarea id=\"message\" rows=\"6\" maxlength=\"3000\"></textarea>\n<button id=\"route\" type=\"button\">Route this inquiry</button><div id=\"result\" class=\"result\" aria-live=\"polite\" role=\"status\"></div></section>\n<section class=\"card\"><h2>2. What a paid pilot would add</h2><p>With your approval: a real inbox or webform trigger, tool-specific rules or AI-assisted classification, CRM/ticket destination, deduplication, an exception queue and measurable processing logs. We would verify security and accuracy before enabling writes.</p><p><a href=\"/automation\">Request a scoped business pilot →</a></p></section>\n<script>\nconst samples={\n lead:'Hello, we want a product demo and a quote for 30 team members. Please connect us with sales. Our budget is under review.',\n support:'Our account dashboard is not working and we need support. The issue started this morning and customers cannot log in.',\n finance:'Please review this purchase order and supplier invoice; there is a mismatch in billing quantities and payment terms.',\n ambiguous:'Hello, can someone contact our team? We have a question and are not sure who should handle it.'\n};\nconst definitions=[\n {name:'Sales / CRM review',terms:['demo','quote','pricing','proposal','purchase','sales','budget']},\n {name:'Support queue',terms:['support','issue','not working','cannot log in','error','bug','refund']},\n {name:'Operations / finance review',terms:['invoice','purchase order','supplier','billing','payment terms','quantities']}\n];\nconst select=document.querySelector('#sample'),input=document.querySelector('#message'),result=document.querySelector('#result');\nfunction populate(){input.value=samples[select.value];result.textContent='Choose Route this inquiry to see the recommendation.'}\nfunction route(text){\n const normalized=text.toLowerCase();\n const scored=definitions.map(group=>({...group,matches:group.terms.filter(term=>normalized.includes(term))}));\n const strongest=Math.max(...scored.map(x=>x.matches.length));\n const leaders=scored.filter(x=>x.matches.length===strongest);\n if(strongest===0||leaders.length!==1)return {queue:'Human triage',signals:'Insufficient or conflicting signals',confidence:'Not assessed',next:'Request clarification before assignment.'};\n const winner=leaders[0];\n const urgency=/\\b(urgent|emergency|asap|immediately)\\b/.test(normalized);\n return {queue:winner.name,signals:winner.matches.join(', '),confidence:'Rule match only; no model confidence',next:urgency?'Flag urgency for human verification before prioritization.':'Queue for human approval before any customer-facing action.'};\n}\ndocument.querySelector('#route').addEventListener('click',()=>{\n const text=input.value.trim();\n if(!text){result.textContent='Enter a fictional example inquiry first.';return}\n const decision=route(text);\n result.textContent='Suggested queue: '+decision.queue+'\\nMatched signals: '+decision.signals+'\\nAssessment: '+decision.confidence+'\\nNext step: '+decision.next;\n});\nselect.addEventListener('change',populate);populate();\n</script></main></body></html>";

const LEADOPS_HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>LeadOps CSV Pilot | TaskForge AI</title><meta name=\"description\" content=\"Try a free browser-only B2B lead routing pilot with CSV import, duplicate flags, deterministic classification, and safe CSV export.\">\n<link rel=\"canonical\" href=\"https://taskforge-ai.pages.dev/automation/leadops\">\n<style>body{background:#0b1020;color:#eef2ff;font-family:system-ui,sans-serif;margin:0}main{max-width:950px;margin:auto;padding:38px 22px}h1{font-size:clamp(31px,5vw,56px);line-height:1.07}p{color:#bac7dc;line-height:1.6}.card{background:#11182b;border:1px solid #2e3b54;border-radius:16px;margin:20px 0;padding:22px}button{background:#9fe6b8;color:#102419;border:0;padding:13px 17px;font-weight:750;border-radius:9px;cursor:pointer;margin:5px 8px 5px 0}button:disabled{opacity:.45}input[type=file]{display:block;margin:14px 0;color:#eee}a{color:#9fe6b8}textarea{display:block;box-sizing:border-box;width:100%;min-height:150px;background:#071126;color:white;border:1px solid #50617c;border-radius:9px;padding:12px}label{display:block;margin:10px 0}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:10px;border-bottom:1px solid #30405c;text-align:left;vertical-align:top;word-break:break-word}.scroll{overflow-x:auto}th{color:#9fe6b8}.muted{font-size:13px;color:#a9bad4}#status{color:#9fe6b8}a:focus-visible,button:focus-visible,textarea:focus-visible,input:focus-visible{outline:3px solid #9fe6b8;outline-offset:2px}</style></head>\n<body><main><a href=\"/automation\">← TaskForge B2B automation</a>\n<h1>LeadOps: make lead intake manageable.</h1>\n<p>A usable, browser-only workflow pilot: import a CSV, classify requests, flag duplicates and export a review queue. No login, external API or paid software required. This is <strong>deterministic rule-based processing, not generative AI</strong>. Human review is required before contacting prospects or making CRM changes.</p>\n<p><a href=\"/automation#b2b-lead\" style=\"display:inline-block;background:#9fe6b8;color:#102419;font-weight:750;padding:13px 19px;border-radius:9px;text-decoration:none\">Discuss a paid pilot for your business →</a></p>\n<section class=\"card\"><h2>1. Load inquiries</h2><p class=\"muted\">CSV must include a <code>message</code> or <code>inquiry</code> column; optional: <code>email</code>, <code>name</code>, <code>company</code>, <code>budget</code>. Max 2 MB, 2,000 data rows and 40 columns. Upload only data you have permission to process. Everything stays on your device.</p>\n<label for=\"lead-file\">CSV file</label><input id=\"lead-file\" type=\"file\" accept=\".csv,text/csv\">\n<button type=\"button\" id=\"sample\">Load fictional example leads</button>\n<label for=\"raw-csv\">Or paste CSV for a quick test</label><textarea id=\"raw-csv\" aria-label=\"CSV content\" spellcheck=\"false\" maxlength=\"2097152\" placeholder=\"name,email,company,message&#10;Taylor,taylor@example.test,Acme,Please send us a demo\"></textarea>\n<button id=\"analyze\" type=\"button\">Analyze and route</button><p id=\"status\" role=\"status\" aria-live=\"polite\"></p></section>\n<section class=\"card\" id=\"results\" hidden><h2>2. Review results</h2><p id=\"metrics\"></p><p class=\"muted\">Duplicates and ambiguous cases stay in the export and are flagged for human review. The tool never sends emails, writes to a CRM or deletes records.</p><div class=\"scroll\"><table><thead><tr><th>Contact</th><th>Suggested queue</th><th>Review flag</th></tr></thead><tbody id=\"rows\"></tbody></table></div>\n<button type=\"button\" id=\"download\">Export reviewed CSV</button></section>\n<section class=\"card\"><h2>3. Make it a real business workflow</h2><p>A paid pilot can connect your approved forms or inbox, map your CRM fields, introduce human approvals, logs and robust rules, and measure exceptions. No integration or savings are promised before feasibility and security review.</p><a href=\"/automation#b2b-lead\">Request a scoped B2B pilot →</a></section>\n<script>\nconst SAMPLE_CSV='name,email,company,message,budget\\nTaylor,taylor@example.test,Acme,\"Can we book a demo and get pricing for 20 seats?\",USD 2000-10000\\nMorgan,morgan@example.test,Northwind,\"Our login dashboard is not working. Please help.\",\\nTaylor,taylor@example.test,Acme,\"Please send a quote for 20 seats.\",USD 2000-10000\\nJamie,jamie@example.test,Supply Co,\"Purchase order and invoice quantities do not match.\",\\nAlex,alex@example.test,Unknown,\"Hello, please call me\",';\nconst file=document.querySelector('#lead-file'),raw=document.querySelector('#raw-csv'),status=document.querySelector('#status'),results=document.querySelector('#results'),metrics=document.querySelector('#metrics'),tbody=document.querySelector('#rows'),download=document.querySelector('#download');\nlet output='';\nfunction normalizeHeader(name){return name.trim().toLowerCase().replace(/[\\s-]+/g,'_')}\nfunction parseCsv(text){\n if(typeof text!=='string'||text.length>2097152)throw Error('CSV exceeds 2 MB.');\n text=text.replace(/^\\uFEFF/,'');\n const rows=[];let row=[],cell='',quoted=false,justClosed=false;\n function finishCell(){if(cell.length>30000)throw Error('Cell exceeds 30,000 characters.');row.push(cell);cell='';justClosed=false;if(row.length>40)throw Error('More than 40 columns.')}\n function finishRow(){finishCell();if(row.some(value=>value.trim()!=='')){rows.push(row);if(rows.length>2001)throw Error('More than 2,000 data rows.')}row=[]}\n for(let i=0;i<text.length;i++){\n  const c=text[i];\n  if(quoted){if(c==='\"'){if(text[i+1]==='\"'){cell+='\"';i++}else{quoted=false;justClosed=true}}else{cell+=c};continue}\n  if(c==='\"'){if(cell.length||justClosed)throw Error('Malformed CSV quotes.');quoted=true;continue}\n  if(c===','){finishCell();continue}\n  if(c==='\\n'||c==='\\r'){finishRow();if(c==='\\r'&&text[i+1]==='\\n')i++;continue}\n  if(justClosed)throw Error('Unexpected characters after a quoted field.');\n  cell+=c;\n }\n if(quoted)throw Error('Unclosed quoted CSV cell.');\n if(row.length||cell.length||justClosed)finishRow();\n if(rows.length<2)throw Error('CSV needs a header and at least one non-empty data row.');\n const header=rows.shift().map(x=>x.replace(/^\\uFEFF/,''));\n if(new Set(header.map(normalizeHeader)).size!==header.length)throw Error('CSV headers must be unique.');\n for(const r of rows)if(r.length!==header.length)throw Error('CSV row has a different number of fields than the header.');\n return {header,rows};\n}\nfunction fieldIndex(header,names){return header.findIndex(x=>names.includes(normalizeHeader(x)))}\nfunction classify(message){\n const t=message.toLowerCase();\n const categories=[\n ['Sales / CRM',/\\b(demo|quote|pricing|proposal|sales|budget|subscription|estimate|trial)\\b/],\n ['Support / service',/\\b(support|not working|unable to log in|cannot log in|broken|bug|outage|help desk|refund)\\b/],\n ['Finance / operations',/\\b(invoice|purchase order|supplier|billing|reconciliation|payment terms|procurement)\\b/]\n ];\n const hit=categories.filter(x=>x[1].test(t));\n return hit.length===1?hit[0][0]:'Human triage';\n}\nfunction analyzeCsv(text){\n const {header,rows}=parseCsv(text);\n const ix={\n  email:fieldIndex(header,['email','work_email','email_address']),\n  name:fieldIndex(header,['name','full_name','contact_name']),\n  company:fieldIndex(header,['company','business','organization','organisation']),\n  message:fieldIndex(header,['message','inquiry','request','description','details','notes'])\n };\n if(ix.message<0)throw Error('CSV needs a message, inquiry or notes column.');\n const seen=new Set(),records=[];let duplicates=0,review=0;\n rows.forEach((cells,i)=>{\n  const get=key=>ix[key]===-1?'':cells[ix[key]].trim();\n  const email=get('email').toLowerCase();\n  const validEmail=/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email);\n  const msg=get('message');\n  const contact=get('name')||get('email')||('Row '+(i+1));\n  const key=validEmail?'email:'+email:(get('name')&&get('company')?'contact:'+get('name').toLowerCase()+'|'+get('company').toLowerCase()+'|'+msg.toLowerCase():'');\n  const duplicate=!!key&&seen.has(key);\n  if(key)seen.add(key);\n  const queue=msg?classify(msg):'Human triage';\n  const flags=[];\n  if(duplicate){flags.push('Possible duplicate');duplicates++}\n  if(ix.email!==-1&&!validEmail)flags.push('Missing/invalid email');\n  if(!msg||msg.length<12)flags.push('Incomplete request');\n  if(queue==='Human triage')flags.push('Ambiguous routing');\n  if(/\\b(urgent|emergency|asap|immediately)\\b/i.test(msg))flags.push('Urgency: human verification');\n  if(flags.length)review++;\n  records.push({cells,contact,queue,flags:flags.join('; ')||'Routine review'});\n });\n return {header,records,duplicates,review};\n}\nfunction safeExportCell(value){\n let out=String(value);\n if(/^[\\s]*[=+\\-@\\t\\r]/.test(out))out=\"'\"+out;\n return '\"'+out.replace(/\"/g,'\"\"')+'\"';\n}\nfunction exportCsv(result){\n return [result.header.concat(['taskforge_suggested_queue','taskforge_review_flags']).map(safeExportCell).join(','),...result.records.map(r=>r.cells.concat([r.queue,r.flags]).map(safeExportCell).join(','))].join('\\r\\n')+'\\r\\n';\n}\nfunction display(result){\n tbody.replaceChildren();\n for(const record of result.records.slice(0,50)){\n  const tr=document.createElement('tr');\n  for(const value of [record.contact,record.queue,record.flags]){\n   const td=document.createElement('td');td.textContent=value;tr.appendChild(td);\n  }tbody.appendChild(tr);\n }\n metrics.textContent=result.records.length+' rows reviewed · '+result.duplicates+' possible duplicates · '+result.review+' rows flagged for human review. Preview shows first 50.';\n output=exportCsv(result);download.disabled=false;results.hidden=false;\n}\ndocument.querySelector('#sample').addEventListener('click',()=>{raw.value=SAMPLE_CSV;file.value='';output='';results.hidden=true;status.textContent='Fictional sample loaded. Choose Analyze and route.'});\ndocument.querySelector('#analyze').addEventListener('click',async()=>{\n output='';results.hidden=true;download.disabled=true;\n try{\n  if(file.files&&file.files[0]){\n   if(file.files[0].size>2097152)throw Error('CSV file exceeds 2 MB.');\n   const text=await file.files[0].text();\n   display(analyzeCsv(text));\n  }else display(analyzeCsv(raw.value));\n  status.textContent='Analysis complete. No data was uploaded to TaskForge.';\n }catch(e){status.textContent=e.message||'Unable to analyze CSV.'}\n});\ndownload.addEventListener('click',()=>{\n if(!output)return;\n const blob=new Blob([output],{type:'text/csv;charset=utf-8'});\n const url=URL.createObjectURL(blob),a=document.createElement('a');\n a.href=url;a.download='taskforge-leadops-reviewed.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);\n});\n</script></main></body></html>";

const CRM_CLEANUP_HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>CRM List Cleanup Pilot | TaskForge AI</title><meta name=\"description\" content=\"Compare client-authorized contact and existing CRM CSV files locally, preserve households, flag duplicates, review exceptions, and safely export CSV.\"><link rel=\"canonical\" href=\"https://taskforge-b2b-preview.taskforge-ai.pages.dev/automation/crm-cleanup\"><style>\nbody{font-family:system-ui,sans-serif;margin:0;background:#0b1020;color:#f7f8fc}main{max-width:960px;margin:auto;padding:42px 22px}h1{font-size:clamp(34px,6vw,56px);line-height:1.1}p{color:#bdc7db;line-height:1.65}.panel{border:1px solid #30425d;background:#121a2c;border-radius:17px;margin:20px 0;padding:22px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:16px}label{display:block;font-weight:650;margin:12px 0 7px}input,textarea{width:100%;box-sizing:border-box;border:1px solid #64738f;border-radius:9px;background:#081324;color:#fff;padding:11px}textarea{min-height:135px;resize:vertical}button{border:0;background:#9fe6b8;color:#082015;font-size:15px;font-weight:750;padding:12px 19px;border-radius:10px;cursor:pointer;margin:10px 12px 10px 0}button:disabled{opacity:.5;cursor:not-allowed}a{color:#9fe6b8}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #31425a;padding:10px;word-break:break-word}th{color:#9fe6b8}.scroll{overflow-x:auto}.muted{font-size:13px;color:#b4c1d8}#feedback{color:#9fe6b8}a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #9fe6b8;outline-offset:3px}</style></head><body><main><p><a href=\"/automation\">← B2B automation services</a></p><h1>CRM cleanup &amp; duplicate review.</h1><p>Compare a new contact list against your existing CRM export, without uploading either file. Distinct people at one address are <strong>never silently merged</strong>. Export the full list with clear review flags, plus an exceptions-only report.</p>\n<section class=\"panel\"><h2>1. Load your two CSV files</h2><p class=\"muted\">Each CSV may contain up to 3,000 data rows and must have at least one of: email, phone, or name with address. Supported headers include name, full_name, first_name, last_name, mailing_address, address, email, phone, telephone. Maximum 2 MB and 35 columns per file. No API calls or uploads are made.</p><div class=\"grid\"><div><label for=\"fresh-file\">New contact list</label><input id=\"fresh-file\" type=\"file\" accept=\".csv,text/csv\"></div><div><label for=\"existing-file\">Existing CRM export</label><input id=\"existing-file\" type=\"file\" accept=\".csv,text/csv\"></div></div><button type=\"button\" id=\"sample\">Load fictional sample records</button><details><summary>Paste CSV instead of selecting files</summary><div class=\"grid\"><div><label for=\"fresh-text\">New contacts CSV</label><textarea id=\"fresh-text\" maxlength=\"2097152\"></textarea></div><div><label for=\"existing-text\">Existing CRM CSV</label><textarea id=\"existing-text\" maxlength=\"2097152\"></textarea></div></div></details><p><button id=\"compare\" type=\"button\">Compare &amp; flag records</button></p><p id=\"feedback\" role=\"status\" aria-live=\"polite\"></p></section>\n<section class=\"panel\" id=\"results\" hidden><h2>2. Review possible matches</h2><p id=\"counts\"></p><p class=\"muted\">Flags are suggestions. No record is deleted or merged, and shared-address households remain separate. CSV formula-looking values are escaped in exports. Rows requiring review remain in the full export.</p><div class=\"scroll\"><table><thead><tr><th>Contact</th><th>Match status</th><th>Reason</th></tr></thead><tbody id=\"rows\"></tbody></table></div><p><button type=\"button\" id=\"export\">Download full review CSV</button><button type=\"button\" id=\"exceptions\">Download exceptions only</button></p></section>\n<section class=\"panel\"><h2>3. Ask about an operations pilot</h2><p>For production work, we would confirm each field's rules, what constitutes a duplicate, and how your team approves contact-list changes. The free tool performs basic normalization and match suggestions; it does not verify US addresses, contact ownership, phone deliverability, or integrate with a live CRM.</p><p><a href=\"/automation\">Request a scoped quote →</a></p></section>\n<script>\nconst EXAMPLE_NEW='name,email,phone,address,city\\nTaylor Lee,taylor@example.test,(713) 555-0101,\"17 Oak St\",Houston\\nJordan Lee,jordan@example.test,(713) 555-0102,\"17 Oak St\",Houston\\nAlex Smith,alex@example.test,7135550103,\"22 Pine St\",Houston\\nTaylor Lee,taylor@example.test,(713) 555-0101,\"17 Oak St\",Houston\\nMissing,,,,\"Houston\"';\nconst EXAMPLE_CRM='name,email,phone,address,city\\nTaylor Lee,taylor@example.test,7135550101,\"17 Oak St\",Houston\\nOther Contact,other@example.test,7135550199,\"22 Pine St\",Houston';\nconst freshFile=document.querySelector('#fresh-file'),existingFile=document.querySelector('#existing-file'),freshText=document.querySelector('#fresh-text'),existingText=document.querySelector('#existing-text'),feedback=document.querySelector('#feedback'),panel=document.querySelector('#results'),counts=document.querySelector('#counts'),tbody=document.querySelector('#rows');\nlet fullOutput='',exceptionOutput='';\nfunction parseCsv(text){\n if(typeof text!=='string'||text.length>2097152)throw Error('CSV exceeds 2 MB.');\n text=text.replace(/^\\uFEFF/,'');\n const rows=[];let row=[],cell='',quoted=false,closed=false;\n const endCell=()=>{if(cell.length>25000)throw Error('CSV cell too long.');row.push(cell);cell='';closed=false;if(row.length>35)throw Error('Too many CSV columns.')};\n const endRow=()=>{endCell();if(row.some(x=>x.trim()))rows.push(row);row=[];if(rows.length>3001)throw Error('More than 3,000 data rows.')};\n for(let i=0;i<text.length;i++){const c=text[i];\n  if(quoted){if(c==='\"'){if(text[i+1]==='\"'){cell+='\"';i++}else{quoted=false;closed=true}}else cell+=c;continue}\n  if(c==='\"'){if(cell.length||closed)throw Error('Malformed quoted CSV value.');quoted=true;continue}\n  if(c===','){endCell();continue}\n  if(c==='\\r'||c==='\\n'){endRow();if(c==='\\r'&&text[i+1]==='\\n')i++;continue}\n  if(closed)throw Error('Unexpected characters after CSV quote.');\n  cell+=c;\n }\n if(quoted)throw Error('Unclosed quoted CSV value.');\n if(row.length||cell||closed)endRow();\n if(rows.length<1)throw Error('Missing CSV header.');\n const header=rows.shift().map(s=>s.trim());\n const names=header.map(s=>s.toLowerCase().replace(/[\\s-]+/g,'_'));\n if(names.some(x=>!x)||new Set(names).size!==names.length)throw Error('CSV headers must be unique and non-empty.');\n for(const r of rows)if(r.length!==header.length)throw Error('CSV row has inconsistent columns.');\n return {header,names,rows};\n}\nconst first=(rec,keys)=>{for(const k of keys){const pos=rec.names.indexOf(k);if(pos>=0)return rec.cells[pos].trim()}return ''};\nconst norm=s=>String(s).trim().toLowerCase().replace(/\\s+/g,' ');\nconst normalEmail=s=>norm(s);\nconst normalPhone=s=>String(s).replace(/\\D/g,'');\nconst normalAddress=s=>norm(s).replace(/[.,]/g,'').replace(/\\bstreet\\b/g,'st').replace(/\\bavenue\\b/g,'ave').replace(/\\s+/g,' ').trim();\nconst showLabel=r=>r.name||r.email||r.phone||('Row '+r.line);\nfunction record(table,cells,line){\n const obj={names:table.names,cells,line};\n const firstName=first(obj,['first_name']),lastName=first(obj,['last_name']);\n const name=first(obj,['name','full_name','contact_name'])||[firstName,lastName].filter(Boolean).join(' ');\n const email=first(obj,['email','email_address','work_email']).toLowerCase();\n const phone=first(obj,['phone','mobile','telephone','phone_number']);\n const address=first(obj,['mailing_address','address','street_address','address_1','street']);\n const city=first(obj,['city','town']);\n return {...obj,name,email,phone,address,city,nName:norm(name),nEmail:normalEmail(email),nPhone:normalPhone(phone),nAddress:normalAddress(address),nCity:norm(city)};\n}\nfunction compare(newCsv,crmCsv){\n const fresh=parseCsv(newCsv),crm=parseCsv(crmCsv);\n const incoming=fresh.rows.map((x,i)=>record(fresh,x,i+2));\n const existing=crm.rows.map((x,i)=>record(crm,x,i+2));\n if(!incoming.length)throw Error('New list needs at least one contact row.');\n const keys=r=>{\n  const k=[];\n  if(/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(r.nEmail))k.push('email:'+r.nEmail);\n  if(r.nPhone.length>=10&&r.nPhone.length<=15)k.push('phone:'+r.nPhone);\n  if(r.nName&&r.nAddress)k.push('name-address:'+r.nName+'|'+r.nAddress+'|'+r.nCity);\n  return k;\n };\n const indexes=new Map(),addresses=new Map();\n function add(r,label){\n  for(const key of keys(r)){const a=indexes.get(key)||[];a.push(label);indexes.set(key,a)}\n  if(r.nAddress){const k=r.nAddress+'|'+r.nCity;const a=addresses.get(k)||[];a.push({name:r.nName,label});addresses.set(k,a)}\n }\n existing.forEach((r,i)=>add(r,'CRM row '+(i+2)));\n const evaluated=[];\n for(const r of incoming){\n  const labels=new Set();\n  for(const key of keys(r))for(const hit of indexes.get(key)||[])labels.add(hit);\n  const sameAddress= r.nAddress?(addresses.get(r.nAddress+'|'+r.nCity)||[]).filter(hit=>hit.name&&r.nName&&hit.name!==r.nName):[];\n  const flags=[];\n  if(labels.size)flags.push('Possible contact duplicate: '+[...labels].slice(0,4).join(', '));\n  if(!labels.size&&sameAddress.length)flags.push('Shared address, distinct names: retain for review');\n  if(!r.name)flags.push('Missing name');\n  if(!r.email&&!r.phone)flags.push('Missing email and phone');\n  if(r.email&&!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(r.nEmail))flags.push('Invalid email syntax');\n  if(r.phone&&(r.nPhone.length<10||r.nPhone.length>15))flags.push('Phone format needs review');\n  if(!keys(r).length)flags.push('Insufficient matching identifiers');\n  let status=labels.size?'POSSIBLE_DUPLICATE':sameAddress.length?'SHARED_ADDRESS_REVIEW':flags.length?'DATA_REVIEW':'NO_MATCH_FOUND';\n  if(!labels.size&&!sameAddress.length&&status==='NO_MATCH_FOUND')flags.push('No exact duplicate identifiers found');\n  evaluated.push({...r,status,reason:flags.join('; '),matches:[...labels].join(' | ')});\n  add(r,'New row '+r.line);\n }\n return {fresh,crm,evaluated,possibleDuplicates:evaluated.filter(x=>x.status==='POSSIBLE_DUPLICATE').length,exceptions:evaluated.filter(x=>x.status!=='NO_MATCH_FOUND').length};\n}\nfunction guardCell(raw){let str=String(raw??'');if(/^[\\s]*[=+\\-@\\t\\r]/.test(str))str=\"'\"+str;return '\"'+str.replace(/\"/g,'\"\"')+'\"'}\nfunction buildExport(data,onlyExceptions=false){\n const header=[...data.fresh.header,'taskforge_match_status','taskforge_review_reason','taskforge_matching_rows'];\n const rows=(onlyExceptions?data.evaluated.filter(r=>r.status!=='NO_MATCH_FOUND'):data.evaluated).map(r=>[...r.cells,r.status,r.reason,r.matches]);\n return [header,...rows].map(row=>row.map(guardCell).join(',')).join('\\r\\n')+'\\r\\n';\n}\nfunction render(data){\n tbody.replaceChildren();for(const r of data.evaluated.slice(0,55)){\n  const tr=document.createElement('tr');\n  for(const val of [showLabel(r),r.status,r.reason]){const td=document.createElement('td');td.textContent=val;tr.appendChild(td)}\n  tbody.appendChild(tr);\n }\n counts.textContent=data.evaluated.length+' new records · '+data.possibleDuplicates+' possible contact duplicates · '+data.exceptions+' records needing review · '+data.crm.rows.length+' existing CRM rows.';\n fullOutput=buildExport(data);exceptionOutput=buildExport(data,true);panel.hidden=false;\n}\ndocument.querySelector('#sample').addEventListener('click',()=>{\n freshFile.value='';existingFile.value='';freshText.value=EXAMPLE_NEW;existingText.value=EXAMPLE_CRM;panel.hidden=true;feedback.textContent='Fictional records loaded. Choose Compare & flag records.';\n});\ndocument.querySelector('#compare').addEventListener('click',async()=>{\n panel.hidden=true;fullOutput='';exceptionOutput='';\n try{\n  if(freshFile.files[0]&&freshFile.files[0].size>2097152||existingFile.files[0]&&existingFile.files[0].size>2097152)throw Error('File exceeds 2 MB.');\n  const fresh=freshFile.files[0]?await freshFile.files[0].text():freshText.value;\n  const existing=existingFile.files[0]?await existingFile.files[0].text():existingText.value;\n  if(!existing.trim())throw Error('Provide an existing CRM CSV (or use fictional sample).');\n  render(compare(fresh,existing));\n  feedback.textContent='Comparison finished locally. Confirm flags before importing any records into your CRM.';\n }catch(err){feedback.textContent=err.message||'CSV comparison failed.'}\n});\nfunction save(content,name){\n if(!content)return;\n const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));\n const anchor=document.createElement('a');anchor.href=url;anchor.download=name;document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(url);\n}\ndocument.querySelector('#export').addEventListener('click',()=>save(fullOutput,'taskforge-crm-full-review.csv'));\ndocument.querySelector('#exceptions').addEventListener('click',()=>save(exceptionOutput,'taskforge-crm-exceptions.csv'));\n</script></main></body></html>";

